export function buildToolCallMessages(pendingToolCalls: ToolCall[]): Message {
  return {
    role: 'assistant',
    content: pendingToolCalls.map(tc => ({
      type: 'tool_use' as const,
      toolUseId: tc.id,
      name: tc.name,
      input: tc.input,
      ...(tc.signature === undefined ? {} : {signature: tc.signature}),
    })),
  };
}
